function validate([text]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 1000) return 'text has 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(text)) return 'text uses lowercase English letters only.';
  return null;
}

