function longestDecomposition(text) {
  let count = 0;
  let left = 0;
  let right = text.length;
  let size = 1;
  while (2 * size <= right - left) {
    const front = text.substring(left, left + size);
    const back = text.substring(right - size, right);
    if (front === back) {
      count += 2;
      left += size;
      right -= size;
      size = 1;
    } else {
      size++;
    }
  }
  return left < right ? count + 1 : count;
}

brute:
function longestDecomposition(text) {
  if (text.length === 0) return 0;
  let best = 1;
  for (let s = 1; 2 * s <= text.length; s++) {
    if (text.slice(0, s) === text.slice(text.length - s)) {
      best = Math.max(best, 2 + longestDecomposition(text.slice(s, text.length - s)));
    }
  }
  return best;
}

