function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (length, alphabet) => {
    let s = '';
    for (let i = 0; i < length; i++) s += letters[Math.floor(rand() * alphabet)];
    return s;
  };
  const large = size === 'large';
  const limit = large ? 1000 : 14;
  const alphabet = int(1, large ? 4 : 3);
  if (rand() < 0.3) return [word(int(large ? 600 : 1, limit), alphabet)];
  // Build mirrored chunks around an optional middle so long decompositions appear.
  const chunks = [];
  let used = 0;
  const longest = large ? int(1, 40) : int(1, 3);
  for (;;) {
    const chunk = word(int(1, longest), alphabet);
    if (2 * (used + chunk.length) > limit - (large ? 20 : 2)) break;
    chunks.push(chunk);
    used += chunk.length;
    if (!large && rand() < 0.3) break;
  }
  const middle = word(int(0, large ? 20 : 2), alphabet);
  const text = chunks.join('') + middle + chunks.slice().reverse().join('');
  return [text.length ? text : word(1, alphabet)];
}
